/*
 * prog21_date_validator
 *
 * The original binary implements a small state‑machine that validates a
 * date supplied on the command line.  The observable behaviour is:
 *
 *   - If the program is invoked without an argument it prints "INVALID".
 *   - The argument must be exactly ten characters long and have the form
 *     YYYY-MM-DD (four digits, a dash, two digits, a dash, two digits).
 *   - All characters other than the two dashes must be decimal digits.
 *   - The month must be in the range 1‑12.
 *   - The day must be valid for the given month, taking leap years into
 *     account (February has 29 days in a leap year, otherwise 28).
 *   - If all checks succeed the program prints "VALID", otherwise it prints
 *     "INVALID".
 *
 * The implementation below reproduces this observable behaviour without
 * recreating the obfuscated control‑flow of the original binary.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

static int is_leap_year(int year)
{
    /* Leap year rule: divisible by 4, but not by 100 unless also by 400 */
    if (year % 4 != 0) return 0;
    if (year % 100 != 0) return 1;
    return (year % 400 == 0);
}

static int days_in_month(int year, int month)
{
    static const int dim[12] = {
        31, 28, 31, 30, 31, 30,
        31, 31, 30, 31, 30, 31
    };

    if (month == 2 && is_leap_year(year))
        return 29;
    return dim[month - 1];
}

int main(int argc, char *argv[])
{
    const char *msg_invalid = "INVALID";
    const char *msg_valid   = "VALID";

    if (argc < 2) {
        puts(msg_invalid);
        return 0;
    }

    const char *s = argv[1];
    size_t len = strlen(s);

    /* Must be exactly "YYYY-MM-DD" */
    if (len != 10 || s[4] != '-' || s[7] != '-') {
        puts(msg_invalid);
        return 0;
    }

    /* All other characters must be digits */
    for (int i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) continue;
        if (!isdigit((unsigned char)s[i])) {
            puts(msg_invalid);
            return 0;
        }
    }

    /* Convert the three fields */
    int year  = (s[0] - '0') * 1000 +
                (s[1] - '0') * 100  +
                (s[2] - '0') * 10   +
                (s[3] - '0');

    int month = (s[5] - '0') * 10 + (s[6] - '0');
    int day   = (s[8] - '0') * 10 + (s[9] - '0');

    /* Basic range checks */
    if (month < 1 || month > 12) {
        puts(msg_invalid);
        return 0;
    }

    if (day < 1 || day > days_in_month(year, month)) {
        puts(msg_invalid);
        return 0;
    }

    /* All checks passed */
    puts(msg_valid);
    return 0;
}
